import { get, subscribe } from '../app/store.js';
import { registerComponentPoll } from '../app/component-poll.js';
import { TX_CONFIRMED_EVENT } from '../app/contracts.js';
import { boonTypePresentation } from '../app/boons.js';
import { displayEth } from '../app/scaling.js';
import {
  SACRIFICE_DEITIES, SACRIFICE_SLOTS_PER_POOL, MIN_BOON_QUOTE_WEI,
  parseBoonWager, readSacrifices, readSacrificeHistory, sacrificeStanding,
  sacrificeAnySlotChance, sacrificeQuote,
} from '../app/sacrifices.js';

// The protocol boon draw has no transaction of its own (audit c5eaf15a): an ordinary ETH
// Degenerette bet on the Vault's XRP hero (symbol 0) or sDGNRS's ETH hero (symbol 6) IS the
// entry. This panel shows tomorrow's three boons per deity, today's pool, the wallet's own
// standing, and what a hero bet of the previewed size would weigh — nothing here signs.
let readState = readSacrifices;
let readHistory = readSacrificeHistory;

/** Raw chain wei → a short display-ETH string (testnet amounts are rescaled for display). */
export function formatBoonEth(wei) {
  if (wei == null) return '—';
  const text = displayEth(BigInt(wei), 4);
  return text.includes('.') ? text.replace(/0+$/, '').replace(/\.$/, '') : text;
}

/** Short, explicit benefits for the six inline boon previews. */
export function compactSacrificeBoon(type, presentation = boonTypePresentation(type)) {
  if (!presentation) return { name: 'Tomorrow', effect: '—' };
  if (Number(type) === 4) return { name: 'Quest', effect: 'Shield' };
  if (Number(type) === 28) return { name: 'Whale', effect: 'Pass' };
  const amount = presentation.effect.match(/[+−-]?\d+(?:\.\d+)?%?/)?.[0] || '—';
  const sign = presentation.direction === 'down' ? '−' : '+';
  const effect = `${sign}${amount.replace(/^[+−-]/, '')}`;
  const asset = presentation.product?.startsWith('degenerette-')
    ? presentation.product.slice('degenerette-'.length).toUpperCase() : '';
  return { name: presentation.name, effect: asset ? `${effect} ${asset}` : effect };
}

function _percent(chance) {
  if (chance == null || !Number.isFinite(chance)) return null;
  const pct = chance * 100;
  if (pct >= 99.95) return '>99.9%';
  if (pct >= 10) return `${pct.toFixed(0)}%`;
  if (pct >= 1) return `${pct.toFixed(1)}%`;
  if (pct >= 0.01) return `${pct.toFixed(2)}%`;
  return '<0.01%';
}

/**
 * Format what the wallet already holds in today's pool and what a previewed hero bet adds.
 *
 * Standing is the SUM of the wallet's existing entries, each carrying its own frozen score
 * snapshot — never a re-quote of the whole position at today's score. The chance is for
 * winning AT LEAST ONE of the three slots, because the pool draws all three independently
 * WITH REPLACEMENT.
 */
export function sacrificeOddsLine({ pool, standing, quote, historyAvailable = true } = {}) {
  if (!pool) return '';
  const entries = Number(pool.entryCount ?? 0);
  const field = `${entries.toLocaleString('en-US')} ${entries === 1 ? 'entry' : 'entries'} · `
    + `${formatBoonEth(pool.totalWageredWei ?? 0n)} ETH bet`;
  if (pool.awardedMask) return `${field} · drawn`;

  const held = standing && standing.count > 0 ? standing : null;
  const parts = [field];
  if (held) {
    const chance = _percent(sacrificeAnySlotChance(held.weight, pool.totalWeight));
    parts.push(`you: ${held.count} ${held.count === 1 ? 'bet' : 'bets'}`
      + `, ${formatBoonEth(held.amountWei)} ETH`
      + (chance ? ` · ${chance} for at least one of ${SACRIFICE_SLOTS_PER_POOL}` : ''));
  } else if (!historyAvailable) {
    parts.push('your standing is unavailable');
  }
  if (quote) {
    // `pool.totalWeight` ALREADY contains this wallet's existing entries, so the post-bet
    // numerator is held + proposed and the denominator is the pool plus the proposed weight.
    const after = sacrificeAnySlotChance(
      BigInt(held?.weight ?? 0n) + BigInt(quote.weight),
      BigInt(pool.totalWeight ?? 0n) + BigInt(quote.weight),
    );
    const pct = _percent(after);
    parts.push(`this bet: ${quote.multiplier.toFixed(2)}× weight` + (pct ? ` → ${pct}` : ''));
  }
  return parts.join(' · ');
}

/** Past awards, newest first, as short readable lines. */
export function sacrificeAwardLines(awards, { limit = 5 } = {}) {
  const byKey = new Map(SACRIFICE_DEITIES.map((deity) => [String(deity.address || '').toLowerCase(), deity.name]));
  return (Array.isArray(awards) ? awards : [])
    .slice()
    .sort((a, b) => Number(b?.day ?? 0) - Number(a?.day ?? 0))
    .slice(0, Math.max(0, limit))
    .map((row) => {
      const name = byKey.get(String(row?.issuer || '').toLowerCase()) || 'a deity';
      // The route serves the same value under both spellings; take either.
      const boon = compactSacrificeBoon(Number(row?.boonType ?? row?.boonKind ?? 0));
      // `day` is the PARTICIPATION day on both events; the award lands on day + 1.
      const day = Number(row?.day);
      const when = Number.isFinite(day) ? `day ${day + 1}` : 'a past day';
      return `${when} · ${name} · ${boon.name} ${boon.effect}`;
    });
}

/** Why a deity's draw cannot take entries right now, or '' while it is open. */
export function sacrificeDrawStatus({ state, deityKey } = {}) {
  if (!state) return 'Boon draw data is unavailable. Try refreshing.';
  if (state.ended) return 'The boon draws are closed. The game has ended.';
  const pool = state.pools?.find((item) => item.key === deityKey);
  if (!pool || pool.awardedMask) return 'This deity’s draw is closed.';
  return '';
}

/** One sentence per deity: how to enter, since there is no button that does it. */
export function sacrificeHowTo(deity) {
  return `Bet ETH on Degenerette with the ${deity.heroName} hero symbol to enter the God of ${deity.name}’s draw `
    + 'for tomorrow’s three boons. Weight is your wager × your activity multiplier; FLIP, WWXRP and gifted bets do not count.';
}

class AppSacrificePanel extends HTMLElement {
  #mounted = false;
  #state = null;
  #history = null;
  #loading = true;
  #seq = 0;
  #queued = false;
  #unsubs = [];
  #stopPoll = null;
  #confirmed = null;

  connectedCallback() {
    if (this.#mounted) return;
    this.#mounted = true;
    this.#shell();
    this.#node('amount').addEventListener('input', () => this.#render());
    for (const key of ['connected.address', 'viewing.address', 'ui.mode', 'ui.chainOk']) {
      this.#unsubs.push(subscribe(key, () => {
        this.#seq += 1;
        this.#state = null;
        this.#history = null;
        this.#queueRefresh();
      }));
    }
    // A confirmed Degenerette bet may have been a hero entry: re-read the pools.
    this.#confirmed = () => this.#queueRefresh();
    document.addEventListener(TX_CONFIRMED_EVENT, this.#confirmed);
    this.#stopPoll = registerComponentPoll(() => this.#refresh(), 30_000);
    this.#refresh();
  }

  disconnectedCallback() {
    this.#mounted = false;
    this.#seq += 1;
    this.#stopPoll?.();
    this.#unsubs.splice(0).forEach((unsubscribe) => unsubscribe());
    document.removeEventListener(TX_CONFIRMED_EVENT, this.#confirmed);
  }

  #node(name) { return this.querySelector(`[data-sacrifice="${name}"]`); }

  #shell() {
    this.innerHTML = `
      <section class="sacrifice" aria-label="Protocol boon draws: bet ETH on a deity hero for tomorrow’s boons">
        ${SACRIFICE_DEITIES.map((deity) => `
          <div class="sacrifice__side" data-deity="${deity.key}" aria-label="The God of ${deity.name}’s boon draw">
            <span class="sacrifice__deity">
            <span class="sacrifice__boons" aria-label="Tomorrow’s three boons">
              ${[0, 1, 2].map((slot) => `
                <span class="sacrifice__boon" data-slot="${slot}">
                  <i class="sacrifice__boon-mark" aria-hidden="true" hidden><img class="sacrifice__boon-icon" alt="" hidden></i>
                  <small data-prize-name>Tomorrow</small><strong data-prize-effect>—</strong>
                </span>`).join('')}
            </span>
            </span>
            <span class="sacrifice__submit sacrifice__submit--info" data-sacrifice="howto-${deity.key}"
                  title="${sacrificeHowTo(deity)}">
              <span class="sacrifice__submit-copy"><b>BET ETH</b><small>ON THE ${deity.heroName} HERO</small><small>TO ENTER</small></span>
              <span class="sacrifice__submit-seal"><img class="sacrifice__submit-badge" src="${deity.symbol}" alt="${deity.heroName} hero" width="50" height="50"></span>
            </span>
            <p class="sacrifice__feedback" data-sacrifice="feedback-${deity.key}" role="status" hidden></p>
          </div>`).join(`
            <label class="sacrifice__amount">
              <input data-sacrifice="amount" type="text" inputmode="decimal" value="0.05"
                     autocomplete="off" spellcheck="false" aria-label="Preview an ETH hero bet"
                     title="Preview what an ETH hero bet of this size would weigh">
              <span>ETH</span>
            </label>`)}
      </section>`;
  }

  #queueRefresh() {
    if (this.#queued || !this.#mounted) return;
    this.#queued = true;
    this.#loading = true;
    this.#render();
    queueMicrotask(() => { this.#queued = false; if (this.#mounted) this.#refresh(); });
  }

  async #refresh() {
    const seq = ++this.#seq;
    this.#loading = true;
    this.#render();
    const player = get('ui.mode') === 'self' ? get('connected.address') : get('viewing.address') || get('connected.address');
    let state = null;
    let history = null;
    try {
      [state, history] = await Promise.all([
        readState({ player }),
        player ? readHistory(player).catch(() => null) : null,
      ]);
    } catch { /* unavailable deployment or RPC */ }
    if (!this.#mounted || seq !== this.#seq) return;
    this.#state = state;
    this.#history = history;
    this.#loading = false;
    this.#render();
  }

  #render() {
    const state = this.#state;
    const input = this.#node('amount');
    const wager = parseBoonWager(input.value);
    input.title = `Preview an ETH hero bet (at least ${formatBoonEth(MIN_BOON_QUOTE_WEI)} ETH)`;
    for (const deity of SACRIFICE_DEITIES) {
      const side = this.querySelector(`[data-deity="${deity.key}"]`);
      const pool = state?.pools.find((item) => item.key === deity.key);
      const tomorrow = state ? `Tomorrow’s boons · day ${state.awardDay}` : 'Tomorrow’s boons';
      side.querySelector('.sacrifice__boons').setAttribute('aria-label', tomorrow);
      side.querySelectorAll('[data-slot]').forEach((slot) => {
        const type = pool?.slots[Number(slot.dataset.slot)];
        const presentation = state?.menuReady && type ? boonTypePresentation(type) : null;
        const boon = compactSacrificeBoon(type, presentation);
        slot.querySelector('[data-prize-name]').textContent = presentation ? boon.name : 'Tomorrow';
        slot.querySelector('[data-prize-effect]').textContent = presentation ? boon.effect : '—';
        slot.title = presentation ? `${tomorrow}: ${presentation.detail}` : (this.#loading ? 'Loading boons…' : 'Boons unavailable');
        const mark = slot.querySelector('.sacrifice__boon-mark');
        const icon = slot.querySelector('.sacrifice__boon-icon');
        mark.hidden = !presentation;
        icon.hidden = !presentation?.icon;
        if (presentation?.icon) icon.src = presentation.icon;
        else icon.removeAttribute('src');
        slot.style.setProperty('--boon-amount', presentation?.amountColor || '#93c5fd');
        slot.dataset.boonProduct = presentation?.product || '';
        slot.dataset.boonDirection = presentation?.direction || '';
        slot.dataset.boonStrength = presentation?.strength || '';
      });
      let line = '';
      if (!this.#loading) {
        const closed = sacrificeDrawStatus({ state, deityKey: deity.key });
        if (closed && !pool) line = closed;
        else {
          const standing = this.#history?.available
            ? sacrificeStanding(this.#history.entries, { issuer: deity.address, day: state?.day })
            : null;
          const quote = !closed && state?.multiplierUnits != null
            ? sacrificeQuote(wager, state.multiplierUnits, pool.totalWeight) : null;
          line = sacrificeOddsLine({ pool, standing, quote, historyAvailable: this.#history?.available !== false });
        }
      }
      const feedback = this.#node(`feedback-${deity.key}`);
      feedback.textContent = line;
      feedback.hidden = !line;
    }
  }
}

if (!customElements.get('app-sacrifice-panel')) customElements.define('app-sacrifice-panel', AppSacrificePanel);

/** Dependency seam for browser fixtures and isolated component tests. */
export function __setSacrificePanelDepsForTest({
  read = readSacrifices,
  history = readSacrificeHistory,
} = {}) {
  readState = read;
  readHistory = history;
}
